"use strict";(globalThis.webpackChunkgrc||=[]).push([[55171],{82151(e){e.exports=JSON.parse('{"citeKey":"sun1990anotherview","slug":"sun-1990-another-view-b7a2","title":"Another View on Parallel Speedup","authors":["X.-H. Sun","L. Ni"],"venue":"Proceedings of the 1990 ACM/IEEE Conference on Supercomputing (SC\'90)","type":"Conference","entryType":"inproceedings","date":"1990","year":1990,"era":"archive","doi":"10.1109/SUPERC.1990.130037","abstract":"This paper presents an alternative view on the speedup of parallel processing. Three models of parallel speedup are studied: fixed-size speedup, fixed-time speedup, and a new memory-bounded speedup model. The memory-bounded model considers the relationship between problem size scaling and available memory, providing a more realistic measure of parallel system performance than traditional fixed-size speedup.","hasAbstract":true,"lede":"This paper presents an alternative view on the speedup of parallel processing.","pages":"324\u2013333","_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);